import { useEffect, useMemo, useState } from "react";
import { RefreshCw } from "lucide-react";
import { fetchAllChestShops, fetchWarpZones } from "@/lib/castiaClient";
import { exactCoins, parseShopLocation, sameShopPosition } from "@/lib/shopLocation";
import { distinctShopRows, stockLabel, stockTimestamp } from "@/lib/shopStock";
import ShopContextMap from './ShopContextMap';

let catalogCache = null;

export default function ShopLocationPanel({ locationKey, onClose, onSelect, onCompare }) {
  const target = useMemo(() => parseShopLocation(locationKey), [locationKey]);
  const hasTarget = !!target;
  const [catalog, setCatalog] = useState(null);
  const [zones, setZones] = useState([]);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(true);
  const [refresh, setRefresh] = useState(0);

  useEffect(() => {
    if (!hasTarget) { setLoading(false); return; }
    const controller = new AbortController();
    setLoading(true); setError(null);
    const cached = !refresh && catalogCache && Date.now() - catalogCache.at < 60000;
    Promise.all([
      cached ? Promise.resolve(catalogCache.rows) : fetchAllChestShops({ signal: controller.signal }).then(result => distinctShopRows(result.shops)),
      fetchWarpZones({ limit: 500, signal: controller.signal }).then(result => result.zones || []).catch(() => []),
    ]).then(([rows, arrivals]) => {
      if (controller.signal.aborted) return;
      if (!cached) catalogCache = { at: Date.now(), rows };
      setCatalog(rows); setZones(arrivals);
    }).catch(e => { if (!controller.signal.aborted) setError(e.message); })
      .finally(() => { if (!controller.signal.aborted) setLoading(false); });
    return () => controller.abort();
  }, [hasTarget, refresh]);

  const selected = target && catalog?.find(row => sameShopPosition(row, target));
  const replaced = selected && target.signFingerprint && selected.signFingerprint !== target.signFingerprint;
  const buttonClass = "inline-flex items-center gap-2 rounded-sm border border-white/10 bg-white/[0.03] px-3 py-2 font-mono text-[10px] font-bold uppercase tracking-[0.16em] text-zinc-300 transition-colors hover:border-indigo-400/50 hover:bg-indigo-500/10 hover:text-white focus-visible:outline focus-visible:outline-2 focus-visible:outline-indigo-400 disabled:opacity-50";

  return <div className="h-full overflow-y-auto custom-scrollbar" data-testid="shop-location-panel">
    <div className="sticky top-0 z-10 flex items-center justify-between gap-3 border-b border-white/10 bg-bg-base/95 px-6 py-4 backdrop-blur-xl sm:px-8">
      <div className="min-w-0"><p className="font-mono text-[10px] uppercase tracking-[0.24em] text-indigo-400">Chest-shop details</p><h2 className="truncate font-heading text-lg font-black tracking-tight">{selected?.itemName || selected?.displayItemName || 'Location & availability'}</h2></div>
      <button className={buttonClass} data-testid="drawer-close" onClick={onClose}>Close</button>
    </div>
    <div className="space-y-6 p-6 sm:p-8">
    {!target ? <p>This location link is invalid.</p> : <>
      <div className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-white/10 bg-white/[0.02] px-4 py-3">
        <p className="font-mono text-[10px] text-zinc-500">{target.serverKey} · {target.dimensionKey.replace("minecraft:", "")} · X {target.x}, Y {target.y}, Z {target.z}</p>
        <button className={buttonClass} disabled={loading} onClick={() => setRefresh(value => value + 1)}><RefreshCw className={loading ? "h-3 w-3 animate-spin" : "h-3 w-3"}/> Refresh data</button>
      </div>
      {loading && <p role="status">Loading observed offers…</p>}
      {error && <p role="alert">Could not load this location: {error}</p>}
      {!loading && !error && !selected && <p>No current observation exists at this location. The shop may have moved or may need rescanning.</p>}
      {!loading && !error && selected && <>
        {replaced && <p role="alert" className="border border-amber-400/50 p-3 text-amber-200">The sign has changed since this link was created. These are the current observations, not the original offer.</p>}
        <section className="relative overflow-hidden rounded-2xl border border-indigo-400/30 bg-indigo-500/[0.06] p-5">
          <div className="absolute -right-8 -top-10 h-36 w-36 rounded-full bg-indigo-400/10 blur-3xl" />
          <div className="relative flex items-start justify-between gap-4"><div><p className="font-mono text-[10px] uppercase tracking-[0.2em] text-indigo-300">Currently Selected Item</p><h3 data-testid="selected-shop-item" className="mt-1 font-heading text-2xl font-black">{selected.itemName || selected.displayItemName}</h3><p className="mt-1 text-sm text-zinc-300">{selected.seller}</p></div><div className="text-right"><p className="font-heading text-2xl font-black text-indigo-300">{exactCoins(selected.unitPrice)}$</p><p className="font-mono text-[10px] uppercase tracking-wider text-zinc-500">each</p></div></div>
          <p className="relative mt-4 font-mono text-xs text-zinc-300">{exactCoins(selected.buyPrice)}$ per purchase · {selected.buyQuantity} item{selected.buyQuantity === 1 ? "" : "s"}</p>
          {selected.tier > 0 && <p>Tier {selected.tier}</p>}
          {Object.entries(selected.enchantments || {}).length > 0 && <p className="text-sm">{Object.entries(selected.enchantments).map(([name, level]) => `${name.replace("minecraft:", "").replaceAll("_", " ")} ${level}`).join(" · ")}</p>}
          <p>{stockLabel(selected)}</p><p className="text-sm text-zinc-400">{stockTimestamp(selected)}</p>
          {selected.requiresTooltipConfirmation && <p className="text-amber-200">Item identity still needs an in-game confirmation.</p>}
          <button className={`${buttonClass} relative mt-4`} onClick={() => onCompare(selected)}>Compare this item’s offers</button>
        </section>
      </>}
      {!loading && !error && catalog && <ShopContextMap target={target} catalog={catalog} zones={zones} onSelect={onSelect} />}
    </>}
  </div></div>;
}
